def decide(g):
    if g["known_monastery"] and not g["consent_or_letter"]:
        return "DENY_EXTERNAL_MONK"
    if g["exacting_or_vicious"]:
        return "ASK_LEAVE"
    if g["reasonable_humble_criticism"]:
        if not g["worthy"]:
            return "REVIEW_THEN_DENY"
        if g["wants_stability"]:
            return "ADMIT_HIGHER_RANK"
        return "GUEST_REVIEW"
    if g["content_and_non_disturbing"]:
        if g["wants_stability"]:
            return "ADMIT_HIGHER_RANK" if g["worthy"] else "ADMIT_ORDINARY_RANK"
        return "GUEST"
    return "REVIEW"
